    fn entry(id: i64, start: &str, duration: i64, billable: bool, stop: bool) -> TimeEntry {
        TimeEntry {
            id,
            start: Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap(),
            duration,
            billable,
            stop: stop.then(|| Utc.timestamp_opt(1, 0).single().unwrap()),
            ..Default::default()
        }
    }

    #[test]
    fn monthly_totals_uses_utc_start_and_invoice_filters() {
        let totals = monthly_totals(&[
            entry(1, "2026-01-31T23:30:00Z", 60, true, true),
            entry(2, "2026-02-01T00:30:00Z", 120, true, true),
            entry(3, "2026-02-01T01:00:00Z", 999, false, true),
            entry(4, "2026-02-01T02:00:00Z", 999, true, false),
        ]);

        assert_eq!(totals.get("2026-01"), Some(&60));
        assert_eq!(totals.get("2026-02"), Some(&120));
        assert_eq!(totals.len(), 2);
    }

